import{_ as t,l as n,o as a,c,v as o,p as d,x as r,d as l,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"编译、链接与入口","description":"","frontmatter":{"title":"编译、链接与入口","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compile-link-entry.md","filePath":"cs/compile-link-entry.md","lastUpdated":1789023840000}'),E={name:"cs/compile-link-entry.md"};function m(h,e,A,_,u,B){const i=n("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="编译、链接与入口" tabindex="-1">编译、链接与入口 <a class="header-anchor" href="#编译、链接与入口" aria-label="Permalink to &quot;编译、链接与入口&quot;">​</a></h1><div class="epigraph"><p>源文件是文本；可执行文件是机器能加载的字节布局。中间隔着翻译、合并符号，以及一条约定好的入口。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 第 7 章整理</footer></div><p>本课是计算机栏第一课。后面的存储区、指针、调用约定、比特与门电路，都默认你会把「写下的语句」和「进程里从某个地址取指」连起来，不再从「计算机是什么」或香农比特另起。后课默认已经读完本课。缺口只有一条：一行 <code>printf</code> 怎样变成 CPU 从固定入口开始执行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>人写的是函数名与类型；加载器要的是按段排好的字节，以及第一条指令的地址。单文件可以假装「编译即镜像」；多文件、库与启动代码必须<strong>链接</strong>——把各编译单元的重定位片段拼成一张地址地图，解析外部符号，填上真正的跳转与数据地址。缺口因此不是 C 语法，而是工具链分工：谁产出可重定位目标，谁把符号绑死，进程为何不从 <code>main</code> 的第一个字节起步。</p><p>把整条链当成黑盒，链接时报 <code>undefined reference</code> 时不知道该改哪个 <code>.o</code>；调试时行号与指令对不上，也是同一缺口。本课只铺流水线；宏展开留给<a href="/cs/preprocessor-preview">预处理器</a>，参数怎么进寄存器留给<a href="/cs/calling-convention-preview">调用约定直觉</a>。</p><h3 id="main-不是第一条指令" tabindex="-1"><code>main</code> 不是第一条指令 <a class="header-anchor" href="#main-不是第一条指令" aria-label="Permalink to &quot;`main` 不是第一条指令&quot;">​</a></h3><p><code>main</code> 是程序员看见的语义入口。进程真实的第一条用户指令在启动例程（C 运行时，常称 crt）：它整理参数与环境，再调用 <code>main</code>，再把返回值交给 <code>exit</code>。把「入口」等同于 <code>int main</code>，后课谈动态链接与进程布局时会对不齐。</p><p><span class="marginnote">K&amp;R 用 <code>cc</code> 驱动预处理、编译、链接。ISO C 把 translation unit 与链接阶段分开：同一标识符如何跨单元合并，是<a href="/cs/module-header">模块与头文件</a>的缺口。CSAPP 第 7 章把目标文件、符号解析与重定位写成程序员可见的机器模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型 C 路径：源文件经过预处理得到编译单元；编译器产出目标文件，内含代码段、数据、重定位表与符号表；链接器合并这些片段，解析 <code>extern</code>，写出可执行镜像或共享库。静态链接把用到的库代码拷进镜像；动态链接把解析推迟到加载或首次调用，见<a href="/cs/dynamic-link-preview">动态链接直觉</a>。</p><p>符号分定义与引用。两个强符号同名则链接失败；未定义符号——声明了却没有任何单元给出定义——同样失败。弱符号与公共符号是实现细节，本课只记：<strong>编译各自产出碎片，链接器负责拼成一张可加载的地址地图</strong>。</p>',12)),(a(),d(p,null,{default:r(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E6%96%87%E4%BB%B6%22%5D%20--%3E%20PP%5B%22%E9%A2%84%E5%A4%84%E7%90%86%22%5D%0A%20%20PP%20--%3E%20COMP%5B%22%E7%BC%96%E8%AF%91%E6%88%90%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20COMP%20--%3E%20LINK%5B%22%E9%93%BE%E6%8E%A5%EF%BC%9A%E8%A7%A3%E6%9E%90%E7%AC%A6%E5%8F%B7%E5%B9%B6%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20LINK%20--%3E%20EXE%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E9%95%9C%E5%83%8F%22%5D%0A%20%20EXE%20--%3E%20CRT%5B%22%E5%90%AF%E5%8A%A8%E4%BE%8B%E7%A8%8B%22%5D%0A%20%20CRT%20--%3E%20MAIN%5B%22%E8%B0%83%E7%94%A8%20main%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>目标文件里的跳转与取址在链接前是占位。链接器按最终布局计算各段基址，把占位改成相对或绝对地址——这就是重定位。没有这一步，多文件程序无法互相调用。加载器把镜像映射进进程之后，控制权交给入口符号；用户代码从 <code>main</code> 才开始有定义。</p><p>理解这条链，下一课才能问：镜像里的全局变量、函数里的自动变量、运行时申请的块，分别落在哪片地址上。那些区域不是语法糖，而是链接与加载留下的分区。</p><p>分别编译能成立，是因为每个目标文件把自己还不知道的地址留成重定位项，而不是把「整个程序」一次吃进编译器。调试信息、栈展开表也可以作为段被链接器搬运，但本课不依赖它们：只要符号解析与入口约定在，后课的栈帧、库与系统调用才有附着点。把入口想成 <code>main</code> 的花括号，会在 crt 初始化全局构造、环境指针、对齐栈之前就去谈程序语义，顺序反了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲指令编码，也不讲虚存如何把文件映成页。ISA 与页表是组成、操作系统后课。也不把预处理器的 <code>#include</code> 守卫在此展开。大模型栏的「编译」是另一套图编译，本栏不写 Transformer。</p><p>后课默认：多文件程序经编译得到带重定位的目标文件，经链接得到镜像，经加载从约定入口进入用户代码。下一课<a href="/cs/stack-heap-static">栈、堆与静态存储</a>在这张镜像上划分寿命。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编译按编译单元产出带重定位的目标文件；链接合并片段并解析符号。</li><li>可执行镜像含代码、数据与入口；<code>main</code> 由启动代码调用，不是进程第一条指令。</li><li>静态链接在链接期并入库代码；动态链接推迟解析。</li><li>后课默认已会把源语句对应到入口之后的地址。</li><li>出处：K&amp;R；ISO/IEC 9899 翻译与环境；CSAPP 第 7 章。</li></ul>',9))])}const P=t(E,[["render",m]]);export{C as __pageData,P as default};
